-- Phase 80: AI Agent Orchestration and Governance control plane.
-- Agents never receive raw SQL/HTTP tools and operational writes remain in ActionEngine.
-- quality: allow-nonconcurrent-index reason=new-empty-ai-governance-tables

create table public.ai_governance_member_permissions(
 organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,
 permissions text[] not null default '{ai_governance:view}',active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),primary key(organization_id,user_id),
 check(permissions <@ array['ai_governance:view','ai_governance:view_runs','ai_governance:view_sensitive_runs','ai_governance:create_agent','ai_governance:edit_agent','ai_governance:publish_agent','ai_governance:manage_prompts','ai_governance:manage_models','ai_governance:manage_tools','ai_governance:manage_autonomy','ai_governance:manage_memory','ai_governance:manage_guardrails','ai_governance:manage_budgets','ai_governance:run_evaluations','ai_governance:approve_waiver','ai_governance:view_costs','ai_governance:view_network','ai_governance:publish_high_risk_agent']::text[])
);
create or replace function private.ai_governance_allowed(target_organization uuid,requested_permission text default 'ai_governance:view') returns boolean language sql stable security definer set search_path='' as $$
 select private.is_superadmin() or (target_organization is not null and (exists(select 1 from public.ai_governance_member_permissions p where p.organization_id=target_organization and p.user_id=(select auth.uid()) and p.active and (requested_permission=any(p.permissions) or 'ai_governance:view_network'=any(p.permissions))) or exists(select 1 from public.organization_members m where m.organization_id=target_organization and m.user_id=(select auth.uid()) and m.active and m.role in('owner','admin'))))
$$;
revoke all on function private.ai_governance_allowed(uuid,text) from public,anon,authenticated;grant execute on function private.ai_governance_allowed(uuid,text) to authenticated,service_role;

create table public.ai_model_profiles(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,profile_key text not null,provider_key text not null,model_key text not null,
 capability_profile text[] not null default '{}',latency_class text not null check(latency_class in('realtime','interactive','standard','batch')),cost_class text not null check(cost_class in('low','medium','high','premium')),
 context_limit integer not null check(context_limit>0),allowed_data_classifications text[] not null default '{public,internal}',allowed_regions text[] not null default '{}',data_handling_policy_ref text,logging_mode text not null default 'metadata_only' check(logging_mode in('none','metadata_only','redacted_diagnostic')),
 contractual_status text not null default 'unreviewed' check(contractual_status in('unreviewed','approved','restricted','prohibited')),status text not null default 'draft' check(status in('draft','active','restricted','deprecated','retired')),fallback_profile_id uuid references public.ai_model_profiles(id) on delete set null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique nulls not distinct(organization_id,profile_key),check(profile_key!~*'(secret|password|token|credential)')
);
create table public.ai_agents(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_key text not null,name text not null,description text,domain text not null,
 agent_type text not null check(agent_type in('conversational','operational_copilot','analytical','customer_facing','voice','support','executive','background_assistant','orchestrator','specialist')),
 owner_label text not null,lifecycle_status text not null default 'draft' check(lifecycle_status in('draft','testing','pilot','active','restricted','deprecated','retired')),autonomy_level smallint not null default 0 check(autonomy_level between 0 and 4),default_model_profile_id uuid references public.ai_model_profiles(id) on delete set null,
 policy_set_id uuid references public.policy_sets(id) on delete set null,knowledge_scope_id uuid,risk_level text not null default 'medium' check(risk_level in('low','medium','high','critical')),customer_facing boolean not null default false,platform_internal boolean not null default false,active_version_id uuid,feature_key text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique nulls not distinct(organization_id,agent_key),check(autonomy_level<5)
);
create table public.ai_prompt_definitions(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_id uuid references public.ai_agents(id) on delete cascade,prompt_key text not null,purpose text not null,
 prompt_type text not null check(prompt_type in('system','developer','task','tool_instruction','summarization','evaluation','handoff')),version integer not null check(version>0),status text not null default 'draft' check(status in('draft','review','approved','published','superseded','archived')),
 template text not null,variables_schema jsonb not null default '{"type":"object","additionalProperties":false}',owner_label text not null,content_hash text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),published_at timestamptz,unique nulls not distinct(organization_id,prompt_key,version),unique nulls not distinct(organization_id,prompt_key,content_hash),
 check(template!~*'(api[_ -]?key|access[_ -]?token|refresh[_ -]?token|password|private[_ -]?key)\s*[:=]'),check(jsonb_typeof(variables_schema)='object')
);
create table public.ai_guardrail_profiles(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,profile_key text not null,name text not null,version integer not null default 1,status text not null default 'draft' check(status in('draft','testing','active','deprecated','retired')),
 allowed_domains text[] not null default '{}',prohibited_actions text[] not null default '{}',confirmation_requirements jsonb not null default '{}',output_constraints jsonb not null default '{}',data_access_rules jsonb not null default '{}',tool_constraints jsonb not null default '{}',policy_set_id uuid references public.policy_sets(id) on delete set null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique nulls not distinct(organization_id,profile_key,version)
);
create table public.ai_memory_policies(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,policy_key text not null,name text not null,version integer not null default 1,status text not null default 'draft' check(status in('draft','active','deprecated','retired')),
 allowed_memory_types text[] not null default '{session,task}',allowed_scope_types text[] not null default '{task,conversation}',default_ttl_seconds integer check(default_ttl_seconds between 60 and 31536000),max_ttl_seconds integer check(max_ttl_seconds between 60 and 31536000),persistent_write_requires_approval boolean not null default true,store_raw_transcript boolean not null default false,allowed_sensitivities text[] not null default '{public,internal}',retention_policy_ref text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique nulls not distinct(organization_id,policy_key,version),check(store_raw_transcript=false)
);
create table public.ai_autonomy_profiles(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,profile_key text not null,name text not null,version integer not null default 1,level smallint not null check(level between 0 and 4),
 allowed_risk_levels text[] not null default '{low}',action_overrides jsonb not null default '{}',high_risk_ceiling smallint not null default 2 check(high_risk_ceiling between 0 and 2),approval_required_above smallint not null default 2 check(approval_required_above between 0 and 4),status text not null default 'draft' check(status in('draft','active','deprecated','retired')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique nulls not distinct(organization_id,profile_key,version)
);
create table public.ai_agent_versions(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,version integer not null check(version>0),status text not null default 'draft' check(status in('draft','testing','review','approved','pilot','active','superseded','rejected','archived')),
 prompt_version_id uuid not null references public.ai_prompt_definitions(id) on delete restrict,model_profile_id uuid not null references public.ai_model_profiles(id) on delete restrict,toolset_version integer not null check(toolset_version>0),memory_policy_id uuid references public.ai_memory_policies(id) on delete restrict,memory_policy_version integer,guardrail_profile_id uuid not null references public.ai_guardrail_profiles(id) on delete restrict,autonomy_profile_id uuid not null references public.ai_autonomy_profiles(id) on delete restrict,config_hash text not null,change_summary text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),published_by uuid references auth.users(id),published_at timestamptz,unique(agent_id,version),unique(agent_id,config_hash)
);
alter table public.ai_agents add constraint ai_agents_active_version_fk foreign key(active_version_id) references public.ai_agent_versions(id) on delete set null;

create table public.ai_tool_definitions(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,tool_key text not null,name text not null,domain text not null,description text not null,contract_version integer not null default 1 check(contract_version>0),
 input_schema jsonb not null,output_schema jsonb not null,risk_level text not null check(risk_level in('low','medium','high','critical')),execution_mode text not null check(execution_mode in('read_only','draft_action','action_engine_required','approval_required','prohibited_for_agents')),owning_service text not null,data_classifications text[] not null default '{internal}',idempotent boolean not null default false,status text not null default 'draft' check(status in('draft','active','deprecated','retired')),data_contract_ref text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique nulls not distinct(organization_id,tool_key,contract_version),
 check(tool_key!~*'(raw_sql|database_query|arbitrary_http|shell|eval|javascript)'),check(jsonb_typeof(input_schema)='object' and jsonb_typeof(output_schema)='object')
);
create table public.ai_toolsets(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,toolset_key text not null,name text not null,version integer not null default 1,status text not null default 'draft' check(status in('draft','active','deprecated','retired')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique nulls not distinct(organization_id,toolset_key,version));
create table public.ai_toolset_members(toolset_id uuid not null references public.ai_toolsets(id) on delete cascade,tool_id uuid not null references public.ai_tool_definitions(id) on delete restrict,max_calls_per_run integer check(max_calls_per_run between 1 and 100),conditions jsonb not null default '{}',primary key(toolset_id,tool_id));
create table public.ai_agent_tool_permissions(
 id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,tool_id uuid not null references public.ai_tool_definitions(id) on delete cascade,scope_type text not null check(scope_type in('organization','brand','region','store','user','role','conversation','task')),scope_id text,conditions jsonb not null default '{}',max_calls_per_run integer check(max_calls_per_run between 1 and 100),status text not null default 'active' check(status in('active','suspended','expired','revoked')),granted_by uuid not null references auth.users(id),created_at timestamptz not null default now(),expires_at timestamptz,unique(agent_id,tool_id,scope_type,scope_id),check(expires_at is null or expires_at>created_at)
);
create table public.ai_agent_knowledge_scopes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,collection_id uuid references public.knowledge_collections(id) on delete cascade,article_types text[] not null default '{}',audiences text[] not null default '{agent_safe}',domains text[] not null default '{}',scope_type text not null check(scope_type in('organization','brand','region','store','role','team')),scope_id text,customer_safe_only boolean not null default false,status text not null default 'active' check(status in('active','suspended','revoked')),created_at timestamptz not null default now());

create table public.ai_agent_budget_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,scope_type text not null check(scope_type in('tenant','store','user','feature','agent')),scope_id text,max_cost_per_run numeric(18,8) not null check(max_cost_per_run>0),max_cost_per_day numeric(18,8) not null check(max_cost_per_day>0),max_tool_calls integer not null check(max_tool_calls between 1 and 100),max_model_calls integer not null check(max_model_calls between 1 and 100),max_runtime_ms integer not null check(max_runtime_ms between 1000 and 3600000),behavior_on_limit text not null check(behavior_on_limit in('stop','degrade_model','require_approval','return_partial_result')),status text not null default 'active' check(status in('active','suspended','expired')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(agent_id,scope_type,scope_id));
create table public.ai_agent_rate_limits(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,scope_type text not null check(scope_type in('tenant','user','agent','feature')),scope_id text,requests_per_minute integer not null check(requests_per_minute>0),concurrent_runs integer not null check(concurrent_runs>0),daily_runs integer not null check(daily_runs>0),status text not null default 'active' check(status in('active','suspended','expired')),created_at timestamptz not null default now(),unique(agent_id,scope_type,scope_id));
create table public.ai_degraded_mode_profiles(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,profile_key text not null,mode text not null check(mode in('human_inbox','static_faq','rule_based_ordering','read_only_analytics','disable_proactive','approved_model_fallback')),trigger_types text[] not null default '{}',fallback_model_profile_id uuid references public.ai_model_profiles(id),customer_message text,core_operations_unaffected boolean not null default true,status text not null default 'active' check(status in('active','suspended','retired')),created_at timestamptz not null default now(),unique(agent_id,profile_key));

create table public.ai_agent_runs(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,agent_id uuid not null references public.ai_agents(id) on delete restrict,agent_version_id uuid not null references public.ai_agent_versions(id) on delete restrict,initiating_actor_type text not null check(initiating_actor_type in('user','customer','service_identity','automation','system')),initiating_actor_id uuid,conversation_ref text,task_ref text,status text not null default 'running' check(status in('running','waiting_human','completed','failed','cancelled','timed_out','budget_exceeded','safety_blocked')),model_profile_id uuid not null references public.ai_model_profiles(id),started_at timestamptz not null default now(),completed_at timestamptz,total_steps integer not null default 0,total_tool_calls integer not null default 0,total_model_calls integer not null default 0,cost_estimate numeric(18,8) not null default 0,latency_ms integer,trace_id uuid not null default gen_random_uuid(),request_summary text,source_refs jsonb not null default '[]',result_summary text,error_code text,logging_level text not null default 'minimal' check(logging_level in('minimal','standard','diagnostic')),check(completed_at is null or completed_at>=started_at),check(total_steps>=0 and total_tool_calls>=0 and total_model_calls>=0 and cost_estimate>=0)
);
create table public.ai_agent_tool_calls(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,run_id uuid not null references public.ai_agent_runs(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete restrict,tool_id uuid not null references public.ai_tool_definitions(id) on delete restrict,tool_contract_version integer not null,input_hash text not null,input_redacted jsonb,output_redacted jsonb,status text not null check(status in('authorized','executing','completed','blocked','failed','timed_out')),policy_decision_ref text,action_request_id uuid,attempt integer not null default 1 check(attempt between 1 and 3),duration_ms integer,cost_estimate numeric(18,8) not null default 0,error_code text,created_at timestamptz not null default now());
create table public.ai_action_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,agent_run_id uuid not null references public.ai_agent_runs(id) on delete cascade,proposed_action text not null,tool_key text not null,input_hash text not null,risk_level text not null check(risk_level in('low','medium','high','critical')),action_engine_request_id uuid references public.copilot_action_requests(id) on delete set null,approval_id uuid references public.internal_approvals(id) on delete set null,status text not null default 'proposed' check(status in('proposed','awaiting_confirmation','awaiting_approval','executing','completed','rejected','failed','expired')),preview jsonb not null default '{}',created_at timestamptz not null default now(),expires_at timestamptz,unique(agent_run_id,tool_key,input_hash));
alter table public.ai_agent_tool_calls add constraint ai_tool_calls_action_request_fk foreign key(action_request_id) references public.ai_action_requests(id) on delete set null;
create table public.ai_memory_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,memory_policy_id uuid not null references public.ai_memory_policies(id) on delete restrict,scope_type text not null check(scope_type in('user','store','tenant','agent','task','conversation')),scope_id text not null,memory_type text not null check(memory_type in('session','task','operational_short_term','approved_profile_memory','shared_domain_memory')),structured_value jsonb not null,content_ref text,source text not null,sensitivity text not null,status text not null default 'active' check(status in('active','expired','deleted','revoked')),created_at timestamptz not null default now(),expires_at timestamptz,deleted_at timestamptz,check(jsonb_typeof(structured_value)='object'),check(structured_value::text!~*'"(password|secret|access_token|refresh_token|card_number|cvv|private_key)"\s*:'),check(memory_type not in('session','task','operational_short_term') or expires_at is not null));

create table public.ai_workflow_definitions(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,workflow_key text not null,name text not null,version integer not null default 1,status text not null default 'draft' check(status in('draft','testing','approved','active','deprecated','retired')),communication_mode text not null check(communication_mode in('synchronous_chat','async_workflow','background_analysis')),definition jsonb not null,owner_label text not null,max_steps integer not null check(max_steps between 1 and 64),max_runtime_ms integer not null check(max_runtime_ms between 1000 and 3600000),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique nulls not distinct(organization_id,workflow_key,version),check(definition::text!~*'"(script|javascript|sql|shell|arbitrary_http)"\s*:'));
create table public.ai_orchestration_workflows(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,parent_run_id uuid not null references public.ai_agent_runs(id) on delete cascade,workflow_definition_id uuid not null references public.ai_workflow_definitions(id) on delete restrict,status text not null default 'running' check(status in('running','waiting_human','completed','failed','cancelled','timed_out','budget_exceeded')),current_step text,checkpoint jsonb not null default '{}',depth smallint not null default 0 check(depth between 0 and 8),child_run_count smallint not null default 0 check(child_run_count between 0 and 32),shared_cost_budget numeric(18,8) not null check(shared_cost_budget>=0),spent_cost numeric(18,8) not null default 0 check(spent_cost>=0),started_at timestamptz not null default now(),completed_at timestamptz);
create table public.ai_agent_handoffs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,parent_run_id uuid not null references public.ai_agent_runs(id) on delete cascade,source_agent_id uuid not null references public.ai_agents(id),target_agent_id uuid not null references public.ai_agents(id),child_run_id uuid references public.ai_agent_runs(id) on delete set null,task_summary text not null,context_refs text[] not null default '{}',scope jsonb not null default '{}',depth smallint not null check(depth between 1 and 8),status text not null default 'proposed' check(status in('proposed','authorized','running','completed','failed','blocked','cancelled')),created_at timestamptz not null default now(),check(source_agent_id<>target_agent_id),check(cardinality(context_refs)<=20));

create table public.ai_evaluation_suites(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,suite_key text not null,name text not null,evaluation_type text not null check(evaluation_type in('correctness','tool_use','grounding','safety','policy_compliance','latency','cost','task_completion','customer_experience','red_team')),version integer not null default 1,status text not null default 'draft' check(status in('draft','active','deprecated','archived')),critical boolean not null default false,golden_dataset_version text not null,created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique nulls not distinct(organization_id,suite_key,version));
create table public.ai_evaluation_cases(id uuid primary key default gen_random_uuid(),suite_id uuid not null references public.ai_evaluation_suites(id) on delete cascade,name text not null,input_fixture jsonb not null,context_fixture jsonb not null default '{}',expected_behavior jsonb not null,required_tools text[] not null default '{}',prohibited_actions text[] not null default '{}',scoring_method text not null check(scoring_method in('deterministic','llm_judge','hybrid','human')),sanitized boolean not null default true,active boolean not null default true,created_at timestamptz not null default now());
create table public.ai_evaluation_results(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_version_id uuid not null references public.ai_agent_versions(id) on delete cascade,model_profile_id uuid not null references public.ai_model_profiles(id),suite_id uuid not null references public.ai_evaluation_suites(id),status text not null check(status in('running','passed','failed','cancelled')),score numeric(8,5),deterministic_pass_rate numeric(8,5) not null check(deterministic_pass_rate between 0 and 1),judge_score numeric(8,5),cost numeric(18,8) not null default 0,latency_ms integer,critical_failures integer not null default 0,security_failures integer not null default 0,failures jsonb not null default '[]',started_at timestamptz not null default now(),completed_at timestamptz);
create table public.ai_evaluation_waivers(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_version_id uuid not null references public.ai_agent_versions(id) on delete cascade,evaluation_result_id uuid not null references public.ai_evaluation_results(id) on delete cascade,failed_check text not null,reason text not null,risk_accepted text not null,approver_id uuid not null references auth.users(id),approval_id uuid references public.internal_approvals(id),critical_failure boolean not null default false,expires_at timestamptz not null,created_at timestamptz not null default now(),check(critical_failure=false),check(expires_at>created_at));

create table public.ai_agent_changesets(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_id uuid not null references public.ai_agents(id) on delete cascade,title text not null,reason text not null,status text not null default 'draft' check(status in('draft','review','approved','published','rolled_back','failed')),impact_summary jsonb not null default '{}',compatibility_status text not null default 'pending' check(compatibility_status in('pending','valid','invalid')),evaluation_status text not null default 'pending' check(evaluation_status in('pending','passed','failed')),approval_id uuid references public.internal_approvals(id),feature_rollout_id uuid references public.feature_rollouts(id) on delete set null,created_by uuid references auth.users(id),approved_by uuid references auth.users(id),published_by uuid references auth.users(id),created_at timestamptz not null default now(),published_at timestamptz);
create table public.ai_agent_changeset_items(changeset_id uuid not null references public.ai_agent_changesets(id) on delete cascade,component_type text not null check(component_type in('agent_version','prompt','model','toolset','guardrail','memory_policy','budget','rollout')),component_id uuid not null,previous_component_id uuid,change_type text not null check(change_type in('add','update','remove','rollback')),primary key(changeset_id,component_type,component_id));
create table public.ai_governance_incidents(id uuid primary key default gen_random_uuid(),organization_id uuid references public.organizations(id) on delete cascade,agent_id uuid references public.ai_agents(id),agent_version_id uuid references public.ai_agent_versions(id),model_profile_id uuid references public.ai_model_profiles(id),prompt_version_id uuid references public.ai_prompt_definitions(id),tool_id uuid references public.ai_tool_definitions(id),incident_type text not null check(incident_type in('cross_tenant_attempt','tool_failure_spike','runaway_cost','provider_outage','unsafe_action_path','major_hallucination','prompt_injection','rollout_regression')),severity text not null check(severity in('SEV1','SEV2','SEV3','SEV4')),status text not null default 'candidate' check(status in('candidate','confirmed','dismissed','resolved')),operational_incident_id uuid references public.operational_incidents(id) on delete set null,evidence_redacted jsonb not null default '{}',detected_at timestamptz not null default now(),resolved_at timestamptz);
create table public.ai_governance_audit_events(id bigint generated always as identity primary key,organization_id uuid references public.organizations(id) on delete cascade,actor_id uuid references auth.users(id),event_type text not null,entity_type text not null,entity_id text,reason text not null,before_state_redacted jsonb,after_state_redacted jsonb,trace_id uuid,created_at timestamptz not null default now());
create table public.ai_governance_settings(organization_id uuid primary key references public.organizations(id) on delete cascade,enabled boolean not null default true,max_handoff_depth smallint not null default 3 check(max_handoff_depth between 1 and 8),max_child_runs smallint not null default 6 check(max_child_runs between 1 and 32),max_tool_repair_attempts smallint not null default 1 check(max_tool_repair_attempts between 0 and 2),default_logging_level text not null default 'minimal' check(default_logging_level in('minimal','standard','diagnostic')),run_metadata_retention_days integer not null default 90 check(run_metadata_retention_days between 1 and 3650),diagnostic_retention_days integer not null default 7 check(diagnostic_retention_days between 1 and 90),updated_by uuid references auth.users(id),updated_at timestamptz not null default now());

create index ai_agents_org_lifecycle_idx on public.ai_agents(organization_id,lifecycle_status,domain);create index ai_agents_active_version_idx on public.ai_agents(active_version_id) where active_version_id is not null;
create index ai_agent_versions_agent_status_idx on public.ai_agent_versions(agent_id,status,version desc);create index ai_prompts_agent_status_idx on public.ai_prompt_definitions(agent_id,status,version desc);create index ai_tools_org_status_idx on public.ai_tool_definitions(organization_id,status,domain);create index ai_toolsets_org_status_idx on public.ai_toolsets(organization_id,status);
create index ai_toolset_members_tool_idx on public.ai_toolset_members(tool_id);create index ai_permissions_agent_tool_idx on public.ai_agent_tool_permissions(agent_id,tool_id,status);create index ai_permissions_tool_idx on public.ai_agent_tool_permissions(tool_id,status);create index ai_knowledge_agent_idx on public.ai_agent_knowledge_scopes(agent_id,status);
create index ai_runs_org_time_idx on public.ai_agent_runs(organization_id,started_at desc);create index ai_runs_agent_time_idx on public.ai_agent_runs(agent_id,started_at desc);create index ai_runs_status_time_idx on public.ai_agent_runs(status,started_at desc);create index ai_tool_calls_run_idx on public.ai_agent_tool_calls(run_id,created_at);create index ai_tool_calls_tool_time_idx on public.ai_agent_tool_calls(tool_id,created_at desc);create index ai_tool_calls_org_status_idx on public.ai_agent_tool_calls(organization_id,status,created_at desc);create index ai_actions_run_status_idx on public.ai_action_requests(agent_run_id,status);create index ai_actions_approval_idx on public.ai_action_requests(approval_id) where approval_id is not null;create index ai_actions_engine_idx on public.ai_action_requests(action_engine_request_id) where action_engine_request_id is not null;
create index ai_memory_scope_expiry_idx on public.ai_memory_entries(organization_id,scope_type,scope_id,status,expires_at);create index ai_memory_agent_idx on public.ai_memory_entries(agent_id,created_at desc);create index ai_workflows_parent_idx on public.ai_orchestration_workflows(parent_run_id,status);create index ai_handoffs_parent_idx on public.ai_agent_handoffs(parent_run_id,status);create index ai_handoffs_target_idx on public.ai_agent_handoffs(target_agent_id,created_at desc);create index ai_eval_results_version_idx on public.ai_evaluation_results(agent_version_id,started_at desc);create index ai_eval_results_suite_idx on public.ai_evaluation_results(suite_id,started_at desc);create index ai_changesets_agent_idx on public.ai_agent_changesets(agent_id,created_at desc);create index ai_incidents_org_status_idx on public.ai_governance_incidents(organization_id,status,detected_at desc);create index ai_audit_org_time_idx on public.ai_governance_audit_events(organization_id,created_at desc);

do $$ declare t text; begin foreach t in array array['ai_governance_member_permissions','ai_model_profiles','ai_agents','ai_prompt_definitions','ai_guardrail_profiles','ai_memory_policies','ai_autonomy_profiles','ai_agent_versions','ai_tool_definitions','ai_toolsets','ai_toolset_members','ai_agent_tool_permissions','ai_agent_knowledge_scopes','ai_agent_budget_policies','ai_agent_rate_limits','ai_degraded_mode_profiles','ai_agent_runs','ai_agent_tool_calls','ai_action_requests','ai_memory_entries','ai_workflow_definitions','ai_orchestration_workflows','ai_agent_handoffs','ai_evaluation_suites','ai_evaluation_cases','ai_evaluation_results','ai_evaluation_waivers','ai_agent_changesets','ai_agent_changeset_items','ai_governance_incidents','ai_governance_audit_events','ai_governance_settings'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;

-- Explicit grants remain valid after the 2026 Data API auto-exposure change. Browser access is read-only; writes are server-side.
do $$ declare t text; begin foreach t in array array['ai_governance_member_permissions','ai_model_profiles','ai_agents','ai_prompt_definitions','ai_guardrail_profiles','ai_memory_policies','ai_autonomy_profiles','ai_agent_versions','ai_tool_definitions','ai_toolsets','ai_agent_tool_permissions','ai_agent_knowledge_scopes','ai_agent_budget_policies','ai_agent_rate_limits','ai_degraded_mode_profiles','ai_agent_runs','ai_action_requests','ai_memory_entries','ai_workflow_definitions','ai_orchestration_workflows','ai_agent_handoffs','ai_evaluation_suites','ai_evaluation_results','ai_evaluation_waivers','ai_agent_changesets','ai_governance_incidents','ai_governance_audit_events','ai_governance_settings'] loop execute format('create policy %I on public.%I for select to authenticated using((select private.ai_governance_allowed(organization_id,''ai_governance:view'')))','ai_governance_read_'||t,t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
do $$ declare t text; begin foreach t in array array['ai_toolset_members','ai_agent_tool_calls','ai_evaluation_cases','ai_agent_changeset_items'] loop execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
create policy ai_toolset_members_read on public.ai_toolset_members for select to authenticated using(exists(select 1 from public.ai_toolsets s where s.id=toolset_id and (select private.ai_governance_allowed(s.organization_id,'ai_governance:view'))));
create policy ai_tool_calls_read on public.ai_agent_tool_calls for select to authenticated using((select private.ai_governance_allowed(organization_id,'ai_governance:view_runs')));
create policy ai_eval_cases_read on public.ai_evaluation_cases for select to authenticated using(exists(select 1 from public.ai_evaluation_suites s where s.id=suite_id and (select private.ai_governance_allowed(s.organization_id,'ai_governance:view'))));
create policy ai_changeset_items_read on public.ai_agent_changeset_items for select to authenticated using(exists(select 1 from public.ai_agent_changesets c where c.id=changeset_id and (select private.ai_governance_allowed(c.organization_id,'ai_governance:view'))));
grant select on public.ai_toolset_members,public.ai_agent_tool_calls,public.ai_evaluation_cases,public.ai_agent_changeset_items to authenticated;
revoke all on sequence public.ai_agent_tool_calls_id_seq,public.ai_governance_audit_events_id_seq from public,anon,authenticated;grant usage,select on sequence public.ai_agent_tool_calls_id_seq,public.ai_governance_audit_events_id_seq to service_role;

create or replace view public.fact_ai_agent_runs with(security_invoker=true) as select organization_id,agent_id,status,date_trunc('hour',started_at) bucket_at,count(*) runs,avg(latency_ms)::numeric(14,2) avg_latency_ms,sum(cost_estimate) estimated_cost from public.ai_agent_runs group by organization_id,agent_id,status,date_trunc('hour',started_at);
create or replace view public.fact_ai_tool_calls with(security_invoker=true) as select organization_id,agent_id,tool_id,status,date_trunc('hour',created_at) bucket_at,count(*) calls,avg(duration_ms)::numeric(14,2) avg_duration_ms,sum(cost_estimate) estimated_cost from public.ai_agent_tool_calls group by organization_id,agent_id,tool_id,status,date_trunc('hour',created_at);
create or replace view public.fact_ai_actions with(security_invoker=true) as select organization_id,status,risk_level,date_trunc('day',created_at) action_date,count(*) actions from public.ai_action_requests group by organization_id,status,risk_level,date_trunc('day',created_at);
create or replace view public.fact_ai_evaluations with(security_invoker=true) as select organization_id,agent_version_id,suite_id,status,date_trunc('day',started_at) evaluation_date,count(*) runs,avg(score)::numeric(8,5) avg_score,avg(deterministic_pass_rate)::numeric(8,5) deterministic_pass_rate,sum(cost) cost from public.ai_evaluation_results group by organization_id,agent_version_id,suite_id,status,date_trunc('day',started_at);
create or replace view public.fact_ai_costs with(security_invoker=true) as select organization_id,agent_id,date_trunc('day',started_at) cost_date,sum(cost_estimate) estimated_cost,count(*) run_count,count(*) filter(where status='completed') successful_runs from public.ai_agent_runs group by organization_id,agent_id,date_trunc('day',started_at);
create or replace view public.fact_ai_policy_blocks with(security_invoker=true) as select organization_id,date_trunc('day',created_at) block_date,count(*) blocks from public.ai_agent_tool_calls where status='blocked' and policy_decision_ref is not null group by organization_id,date_trunc('day',created_at);
create or replace view public.fact_ai_human_reviews with(security_invoker=true) as select organization_id,date_trunc('day',created_at) review_date,status,count(*) reviews from public.ai_action_requests where status in('awaiting_confirmation','awaiting_approval','rejected') group by organization_id,date_trunc('day',created_at),status;
create or replace view public.dim_ai_agent with(security_invoker=true) as select id,organization_id,agent_key,name,domain,agent_type,lifecycle_status,autonomy_level,risk_level,customer_facing from public.ai_agents;
create or replace view public.dim_ai_agent_version with(security_invoker=true) as select id,organization_id,agent_id,version,status,model_profile_id,toolset_version,memory_policy_version,published_at from public.ai_agent_versions;
create or replace view public.dim_ai_model_profile with(security_invoker=true) as select id,organization_id,profile_key,provider_key,model_key,latency_class,cost_class,status from public.ai_model_profiles;
create or replace view public.dim_ai_tool with(security_invoker=true) as select id,organization_id,tool_key,name,domain,contract_version,risk_level,execution_mode,status from public.ai_tool_definitions;
create or replace view public.dim_ai_run_status with(security_invoker=true) as select * from(values('running'),('waiting_human'),('completed'),('failed'),('cancelled'),('timed_out'),('budget_exceeded'),('safety_blocked'))v(status);
create or replace view public.dim_ai_autonomy_level with(security_invoker=true) as select * from(values(0,'answer_only'),(1,'recommend'),(2,'draft'),(3,'controlled_execute'),(4,'autonomous_bounded'))v(level,name);
grant select on public.fact_ai_agent_runs,public.fact_ai_tool_calls,public.fact_ai_actions,public.fact_ai_evaluations,public.fact_ai_costs,public.fact_ai_policy_blocks,public.fact_ai_human_reviews,public.dim_ai_agent,public.dim_ai_agent_version,public.dim_ai_model_profile,public.dim_ai_tool,public.dim_ai_run_status,public.dim_ai_autonomy_level to authenticated,service_role;

comment on table public.ai_agents is 'Phase 80 registry for existing MasterApp agents. Definitions govern existing implementations; they do not duplicate copilots.';
comment on table public.ai_action_requests is 'AI action proposals only. Operational execution remains in copilot_action_requests/ActionEngine after preview, policy and approval.';
comment on table public.ai_memory_entries is 'Typed scoped memory only; raw unrestricted conversation memory and secrets are prohibited.';
comment on table public.ai_agent_runs is 'Operational run telemetry without private chain-of-thought. Content logging is minimal/redacted by default.';

